/bin/zsh -c "cat > migration.sql <<'EOF'
BEGIN;

CREATE TABLE IF NOT EXISTS pricing_decision (
  subscription_id text PRIMARY KEY REFERENCES subscription(id),
  fee_cents integer NOT NULL
);

-- A decision uses the fee that was in force when the subscription was approved.
-- Check every value that this migration would carry forward before inserting it.
DO "'$$
DECLARE
  invalid_rows text;
  invalid_count bigint;
BEGIN
  SELECT count(*), string_agg(subscription_id, '"', ' ORDER BY subscription_id)
    INTO invalid_count, invalid_rows
  FROM (
    SELECT DISTINCT ON (s.id) s.id AS subscription_id, h.fee_cents
    FROM subscription s
    JOIN pricing_history h ON h.subscription_id = s.id
    WHERE h.effective_from <= s.approved_at
      AND NOT EXISTS (
        SELECT 1 FROM pricing_decision d WHERE d.subscription_id = s.id
      )
    ORDER BY s.id, h.effective_from DESC
  ) approved_fee
  WHERE fee_cents < 0;

  IF invalid_count > 0 THEN
    RAISE EXCEPTION 'Cannot migrate % negative approved fees; subscriptions: %', invalid_count, invalid_rows
      USING ERRCODE = 'P0001';
  END IF;
END "'$$;

INSERT INTO pricing_decision (subscription_id, fee_cents)
SELECT DISTINCT ON (s.id) s.id, h.fee_cents
FROM subscription s
JOIN pricing_history h ON h.subscription_id = s.id
WHERE h.effective_from <= s.approved_at
  AND NOT EXISTS (
    SELECT 1 FROM pricing_decision d WHERE d.subscription_id = s.id
  )
ORDER BY s.id, h.effective_from DESC;

ALTER TABLE pricing_decision
  ADD CONSTRAINT fee_non_negative CHECK (fee_cents >= 0);

COMMIT;
EOF
cat > subscriptions.ts <<'"'EOF'
export const MIN_FEE = 100;

export function getFee(subscription: any) {
  return subscription.pricingDecision?.feeCents
    ?? subscription.terms?.monthlyFeeCents
    ?? MIN_FEE;
}

export function newVersion(previous: any) {
  const { monthlyFeeCents: _redecide, ...decidedTerms } = previous.terms ?? {};
  return { terms: { ...decidedTerms } };
}

export function changedSinceApproval(subscription: any) {
  return getFee(subscription) "'!== subscription.terms.monthlyFeeCents;
}

// Keep accepting the legacy field while old clients still submit it.
export function acceptLegacyTerms(input: any) {
  if (!Number.isInteger(input.monthlyFeeCents)) throw new Error('"'invalid');
  return input;
}
EOF
"

