/bin/zsh -c "cat > schema.sql <<'EOF'
CREATE TABLE subscription (
  id text PRIMARY KEY,
  approved_at date NOT NULL,
  terms jsonb NOT NULL
);
CREATE TABLE pricing_history (
  subscription_id text REFERENCES subscription(id),
  effective_from date NOT NULL,
  fee_cents integer NOT NULL,
  PRIMARY KEY (subscription_id, effective_from)
);
CREATE TABLE pricing_decision (
  subscription_id text PRIMARY KEY REFERENCES subscription(id),
  fee_cents integer NOT NULL
);

DO "'$$
DECLARE
  invalid_rows text;
  invalid_count bigint;
BEGIN
  SELECT count(*), string_agg(subscription_id, '"', ' ORDER BY subscription_id)
    INTO invalid_count, invalid_rows
  FROM (
    SELECT DISTINCT ON (s.id) s.id AS subscription_id, h.fee_cents
    FROM subscription s
    JOIN pricing_history h ON h.subscription_id = s.id
    WHERE h.effective_from <= s.approved_at
    ORDER BY s.id, h.effective_from DESC
  ) approved_fee
  WHERE fee_cents < 0;

  IF invalid_count > 0 THEN
    RAISE EXCEPTION 'Cannot create pricing decisions for % negative approved fees; subscriptions: %', invalid_count, invalid_rows
      USING ERRCODE = 'P0001';
  END IF;
END "'$$;

INSERT INTO pricing_decision (subscription_id, fee_cents)
SELECT DISTINCT ON (s.id) s.id, h.fee_cents
FROM subscription s
JOIN pricing_history h ON h.subscription_id = s.id
WHERE h.effective_from <= s.approved_at
ORDER BY s.id, h.effective_from DESC;

ALTER TABLE pricing_decision
  ADD CONSTRAINT fee_non_negative CHECK (fee_cents >= 0);
EOF
cat > smoke.test.ts <<'"'EOF'
import {test, expect} from 'bun:test';
import {acceptLegacyTerms, changedSinceApproval, getFee, newVersion} from './subscriptions';

test('new decision takes precedence over legacy terms', () =>
  expect(getFee({terms:{monthlyFeeCents:1500},pricingDecision:{feeCents:2500}})).toBe(2500));

test('existing subscription can still read its legacy fee', () =>
  expect(getFee({terms:{monthlyFeeCents:1500}})).toBe(1500));

test('new version copies decided terms but omits fees to be redecided', () => {
  expect(newVersion({terms:{plan:'pro',monthlyFeeCents:1500},pricingDecision:{feeCents:1500}}))
    .toEqual({terms:{plan:'pro'}});
});

test('legacy client input remains accepted', () =>
  expect(acceptLegacyTerms({plan:'pro',monthlyFeeCents:1500}))
    .toEqual({plan:'pro',monthlyFeeCents:1500}));

test('changed approval compares against the stored decision', () =>
  expect(changedSinceApproval({terms:{monthlyFeeCents:1500},pricingDecision:{feeCents:2500}})).toBe(true));
EOF
bun test"

